function (shader) {
        shader.uniforms.frNoseContourStrength = noseContourStrength;
        shader.vertexShader = shader.vertexShader
          .replace('#include <common>', '#include <common>
varying vec3 frNoseSurfaceNormal;
varying vec3 frNoseViewPosition;')
          .replace('#include <project_vertex>', '#include <project_vertex>
frNoseSurfaceNormal = normalize(normalMatrix * normal);
frNoseViewPosition = -mvPosition.xyz;');
        shader.fragmentShader = shader.fragmentShader
          .replace('#include <common>', '#include <common>
varying vec3 frNoseSurfaceNormal;
varying vec3 frNoseViewPosition;
uniform float frNoseContourStrength;')
          .replace('#include <color_fragment>', '#include <color_fragment>
float frNoseFacing = abs(dot(normalize(frNoseSurfaceNormal), normalize(frNoseViewPosition)));
float frNoseContour = mix(0.08, 1.0, smoothstep(0.20, 0.45, frNoseFacing));
diffuseColor.rgb *= mix(1.0, frNoseContour, frNoseContourStrength);');
      }

